package net.officefloor.hq.app.person;

import jakarta.validation.constraints.Size;

/**
 * A person's fields as the form submits them: a name (required), a grade (A, B or C) and the date the grade
 * is in force from (yyyy-mm-dd; blank is the sheet's today, and is kept blank here) and the person's own terms
 * (a whole number of days, 0 or more; blank: none, kept blank here). An edit also sends the version of the person
 * its editor loaded; an add sends none. The contact is kept trimmed and lower-cased (blank: none, kept blank here).
 */
public record PersonRequest(@Size(max = 200) String name, @Size(max = 10) String grade,
        @Size(max = 30) String gradeFrom, Integer version, @Size(max = 30) String terms,
        @Size(max = 200) String contact) {

    /** The terms as a number of days, or null when blank; call only once validated. */
    public Integer termsDays() {
        return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms);
    }

    /** The contact, or null when blank; call only once validated. */
    public String contactOrNull() {
        return contact == null || contact.isEmpty() ? null : contact;
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePersonRequest {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody @Valid PersonRequest request, Out<PersonRequest> body)
            throws InvalidPersonException {
        // The name is kept without surrounding spaces; a blank one is refused.
        String name = request.name() == null ? "" : request.name().strip();
        if (name.isBlank()) {
            throw new InvalidPersonException("A name is required.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim().toUpperCase();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be yyyy-mm-dd.");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,5}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank.");
        }
        String contact = request.contact() == null ? "" : request.contact().strip().toLowerCase(Locale.ROOT);
        body.set(new PersonRequest(name, grade, from, request.version(),
                terms.isEmpty() ? "" : String.valueOf(Integer.parseInt(terms)), contact));
    }
}
