package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import java.util.Objects;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Applies the edit to the person as loaded; refused when the editor loaded an older version. The form's grade
 * is recorded from its from-date (blank: the sheet's today), keeping the grades already recorded — except that a
 * grade left as the row showed it, with the from-date blank, records nothing. The person's own terms become the
 * form's (blank: none), as does their contact; whether either changed is published for the audit.
 */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, SheetRepository sheets, Out<Person> updated,
            Out<PersonTermsChange> termsChange) throws StalePersonException {
        if (request.version() != null && request.version() != person.version()) {
            throw new StalePersonException(person.name());
        }
        Integer terms = request.termsDays();
        String contact = request.contactOrNull();
        termsChange.set(new PersonTermsChange(!Objects.equals(terms, person.terms()),
                !Objects.equals(contact, person.contact())));
        boolean blank = request.gradeFrom() == null || request.gradeFrom().isEmpty();
        if (blank && request.grade().equals(person.grade())) {
            updated.set(person.withName(request.name()).withTerms(terms).withContact(contact));
            return;
        }
        LocalDate today = sheets.today(person.sheetId());
        LocalDate from = blank ? today : LocalDate.parse(request.gradeFrom());
        updated.set(person.withNameAndGrade(request.name(), request.grade(), from, today).withTerms(terms)
                .withContact(contact));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/**
 * A person as the screen shows them; the last statement's due-total and date are null before the first, and
 * {@code retiredFrom} is null while they are not retired; {@code held} is whether they have any hold, {@code holds}
 * each hold, oldest first. {@code grade} is the grade in force on the sheet's today; {@code grades} every grade
 * recorded, each from its from-date. {@code terms} are the person's own terms in days, null when they have none;
 * {@code contact} their contact, null when they have none. {@code clashing} is whether another sheet of the sheet's
 * tree uses their name or any of their aliases as a name or alias. {@code origin} is the sheet they were transferred
 * from, null when they were not transferred here. {@code pastRetirements} are the retirements they were unretired
 * from, oldest first.
 */
public record PersonResponse(long id, String name, String grade, int version, int statementCount, String statedTotal,
        String statementDate, boolean retired, String retiredFrom, boolean held,
        List<Grade> grades, List<HoldDates> holds, Integer terms, String contact,
        boolean clashing, String origin, List<RetirementDates> pastRetirements) {


    /** A grade recorded for the person, from its from-date (yyyy-mm-dd; null: from the beginning of time). */
    public record Grade(String grade, String from) {
    }

    /** A hold on the person, from its from-date to its to-date, both inclusive (yyyy-mm-dd; null: open-ended). */
    public record HoldDates(String from, String to) {
    }

    /** A retirement the person was unretired from, from its from-date to the day they were unretired (yyyy-mm-dd). */
    public record RetirementDates(String from, String to) {
    }

    public static PersonResponse from(Person person, boolean clashing, String origin) {
        return new PersonResponse(person.id(), person.name(), person.grade(), person.version(), person.statementCount(),
                person.statedTotal(), person.statementDate() == null ? null : person.statementDate().toString(),
                person.retired(), person.retiredFrom() == null ? null : person.retiredFrom().toString(),
                person.held(), person.grades().stream()
                        .map((g) -> new Grade(g.grade(), g.from() == null ? null : g.from().toString())).toList(),
                person.holds().stream().map((h) -> new HoldDates(h.from() == null ? null : h.from().toString(),
                        h.to() == null ? null : h.to().toString())).toList(), person.terms(),
                person.contact(), clashing, origin, person.pastRetirements().stream()
                        .map((r) -> new RetirementDates(r.from().toString(), r.to().toString())).toList());
    }
}
package net.officefloor.hq.app.person;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.alias.Alias;
import net.officefloor.hq.app.alias.AliasRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeople {
    public void respond(@Val Sheet sheet, @Val List<Person> people, AliasRepository aliases, NameTree tree,
            PersonRepository repository, ObjectResponse<List<PersonResponse>> response) {
        Set<String> taken = tree.taken(sheet.id());
        Map<Long, List<String>> byPerson = new HashMap<>();
        if (!taken.isEmpty()) {
            for (Alias a : aliases.findAll(sheet.id())) {
                byPerson.computeIfAbsent(a.personId(), (k) -> new java.util.ArrayList<>()).add(a.alias());
            }
        }
        Map<Long, String> origins = repository.origins(sheet.id());
        response.send(people.stream().map((p) -> PersonResponse.from(p,
                NameTree.clashing(taken, p.name(), byPerson.getOrDefault(p.id(), List.of())), origins.get(p.id())))
                .toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, PersonRepository people, NameTree tree,
            ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person, tree.clashing(person, people.aliases(person.sheetId(), person.id())),
                people.origin(person.sheetId(), person.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonRepository repository, Out<Person> saved) throws StalePersonException {
        Person stored = repository.save(person);
        if (stored == null) {
            throw new StalePersonException(person.name());
        }
        saved.set(stored);
    }
}
