    /**
     * Tags as typed (comma separated) in their stored form: each trimmed and lower-cased, blanks and repeats dropped,
     * sorted and comma separated; null when there are none.
     */
    public static String tags(String typed) {
        if (typed == null) {
            return null;
        }
        String tags = Arrays.stream(typed.split(",")).map((t) -> t.strip().toLowerCase(Locale.ROOT))
                .filter((t) -> !t.isEmpty()).distinct().sorted().collect(Collectors.joining(","));
        return tags.isEmpty() ? null : tags;
    }

package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person merged into, as the store holds them now. */
public class RespondWithMerge {
    public void respond(@Val Merge merge, PersonRepository people, NameTree tree,
            ObjectResponse<PersonResponse> response) {
        Person into = people.find(merge.into().sheetId(), merge.into().id());
        response.send(PersonResponse.from(into, tree.clashing(into, people.aliases(into.sheetId(), into.id())),
                people.origin(into.sheetId(), into.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person as they arrived on the other sheet. */
public class RespondWithTransfer {
    public void respond(@Val Transferred transferred, PersonRepository people, NameTree tree,
            ObjectResponse<PersonResponse> response) {
        Person person = transferred.person();
        response.send(PersonResponse.from(person, tree.clashing(person, people.aliases(person.sheetId(), person.id())),
                people.origin(person.sheetId(), person.id())));
    }
}

